use numpy::{PyArray1, PyReadonlyArray1}; use pyo3::prelude::*; use pyo3::exceptions::PyValueError; use taflow::stream::{EaseOfMovement,ForceIndex,Vwap};
#[pyclass] pub struct VwapOperator{inner:Vwap,outputs:Vec<f64>}
#[pymethods] impl VwapOperator{#[new]fn new(timeperiod:usize)->PyResult<Self>{Ok(Self{inner:Vwap::new(timeperiod).map_err(|e|PyValueError::new_err(e.to_string()))?,outputs:Vec::new()})}fn append(&mut self,high:f64,low:f64,close:f64,volume:f64)->Option<f64>{let v=self.inner.append(high,low,close,volume);self.outputs.push(v.unwrap_or(f64::NAN));v}fn extend(&mut self,high:PyReadonlyArray1<f64>,low:PyReadonlyArray1<f64>,close:PyReadonlyArray1<f64>,volume:PyReadonlyArray1<f64>)->PyResult<()>{let(h,l,c,vol)=(high.as_slice()?,low.as_slice()?,close.as_slice()?,volume.as_slice()?);if h.len()!=l.len()||h.len()!=c.len()||h.len()!=vol.len(){return Err(PyValueError::new_err("inputs must have equal lengths"));}for(((&h,&l),&c),&v)in h.iter().zip(l).zip(c).zip(vol){self.append(h,l,c,v);}Ok(())}fn compute<'py>(&self,py:Python<'py>)->Bound<'py,PyArray1<f64>>{PyArray1::from_vec(py,self.outputs.clone())}#[getter]fn value(&self)->Option<f64>{self.inner.value()}fn reset(&mut self){self.inner.reset();self.outputs.clear();}}
#[pyclass] pub struct ForceIndexOperator{inner:ForceIndex,outputs:Vec<f64>}
#[pymethods] impl ForceIndexOperator{#[new]fn new()->Self{Self{inner:ForceIndex::new(),outputs:Vec::new()}}fn append(&mut self,close:f64,volume:f64)->Option<f64>{let v=self.inner.append(close,volume);self.outputs.push(v.unwrap_or(f64::NAN));v}fn extend(&mut self,close:PyReadonlyArray1<f64>,volume:PyReadonlyArray1<f64>)->PyResult<()>{let(c,v)=(close.as_slice()?,volume.as_slice()?);if c.len()!=v.len(){return Err(PyValueError::new_err("inputs must have equal lengths"));}for(&c,&v)in c.iter().zip(v){self.append(c,v);}Ok(())}fn compute<'py>(&self,py:Python<'py>)->Bound<'py,PyArray1<f64>>{PyArray1::from_vec(py,self.outputs.clone())}#[getter]fn value(&self)->Option<f64>{self.inner.value()}fn reset(&mut self){self.inner.reset();self.outputs.clear();}}
#[pyclass] pub struct EaseOfMovementOperator{inner:EaseOfMovement,outputs:Vec<f64>}
#[pymethods] impl EaseOfMovementOperator{#[new]fn new()->Self{Self{inner:EaseOfMovement::new(),outputs:Vec::new()}}fn append(&mut self,high:f64,low:f64,volume:f64)->Option<f64>{let v=self.inner.append(high,low,volume);self.outputs.push(v.unwrap_or(f64::NAN));v}fn extend(&mut self,high:PyReadonlyArray1<f64>,low:PyReadonlyArray1<f64>,volume:PyReadonlyArray1<f64>)->PyResult<()>{let(h,l,v)=(high.as_slice()?,low.as_slice()?,volume.as_slice()?);if h.len()!=l.len()||h.len()!=v.len(){return Err(PyValueError::new_err("inputs must have equal lengths"));}for((&h,&l),&v)in h.iter().zip(l).zip(v){self.append(h,l,v);}Ok(())}fn compute<'py>(&self,py:Python<'py>)->Bound<'py,PyArray1<f64>>{PyArray1::from_vec(py,self.outputs.clone())}#[getter]fn value(&self)->Option<f64>{self.inner.value()}fn reset(&mut self){self.inner.reset();self.outputs.clear();}}
